    function run(address newOwner) public {
        address beforeOwner = c.owner();
        require(msg.sender == beforeOwner);

        c.transferOwnership(newOwner);

        assert(c.owner() == newOwner);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bool asOwner) public {
        address newOwner = address(uint160(uint256(keccak256(abi.encodePacked(asOwner)))));
        bool reverted;
        address savedOwner = c.owner();
        try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
        if (asOwner) {
            // if called as owner (since msg.sender == owner), transferOwnership succeeded and owner == newOwner
            assert(!reverted && c.owner() == newOwner);
        } else {
            // if called as non-owner, transferOwnership reverted and owner unchanged
            assert(reverted && c.owner() == savedOwner);
        }
    }
}

